-- Mage S "wow" set with Mana costs (Q chose Apply, 2026-10-16). Backup: /mnt/project-files/backups/mg-s-cards-before-wow-2026-10-16.md
update cards set cost = 2, effect_json = '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"pierce","target":"following"},{"a":"addDmg","target":"following","n":3}]}]'::jsonb, effect = 'Before action, if you play Strike: All following cards ignore Block, all following cards +3 dmg' where id = 'MG-001';
update cards set cost = 3, effect_json = '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"chainLength","op":">=","n":3}],"do":[{"a":"mulDmg","target":"this","pct":200}]},{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"chainLength","op":">=","n":5}],"do":[{"a":"mulDmg","target":"this","pct":150}]}]'::jsonb, effect = 'Before action, if you play Strike and your chain has 3+ cards: This card dmg x2 / Before action, if you play Strike and your chain has 5+ cards: This card dmg 150%' where id = 'MG-002';
update cards set cost = 3, effect_json = '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"pierce","target":"this"}]},{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"silenced","who":"enemy"}],"do":[{"a":"mulDmg","target":"this","pct":300}]}]'::jsonb, effect = 'Before action, if you play Strike: This card ignores Block / Before action, if you play Strike and opponent is Silenced: This card dmg x3' where id = 'MG-003';
update cards set cost = 3, effect_json = '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"}],"do":[{"a":"status","who":"enemy","kind":"noStrike","turns":1},{"a":"status","who":"enemy","kind":"noBlock","turns":1}]}]'::jsonb, effect = 'After action, if you play Strike and this card hits clean: Opponent can''t Strike next turn, opponent can''t Block next turn' where id = 'MG-004';
update cards set cost = 1, effect_json = '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"}],"do":[{"a":"status","who":"enemy","kind":"noBlock","turns":2}]}]'::jsonb, effect = 'After action, if you play Strike and this card hits clean: Opponent can''t Block for 2 turns' where id = 'MG-005';
update cards set cost = 2, effect_json = '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"loseHp","who":"enemy","n":5,"per":"enemyCard"}]}]'::jsonb, effect = 'After action, if you play Strike: Opponent lose 5 HP per card in opponent''s hand' where id = 'MG-006';
update cards set cost = 0, effect_json = '[{"hook":"onHeld","if":[{"c":"enemyAction","a":"strike"}],"do":[{"a":"status","who":"enemy","kind":"noCharge","turns":1},{"a":"status","who":"enemy","kind":"silence","turns":1}]}]'::jsonb, effect = 'Every turn (Hold), if opponent plays Strike: Opponent can''t Charge next turn, opponent Silenced (card effects off) next turn' where id = 'MG-007';
update cards set cost = 1, effect_json = '[{"hook":"modify","if":[{"c":"enemyAction","a":"strike"}],"do":[{"a":"mulDmg","target":"enemyAll","pct":50}]}]'::jsonb, effect = 'Before action, if opponent plays Strike: All opponent''s cards lose 50% dmg' where id = 'MG-008';
update cards set cost = 2, effect_json = '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"hitResult","r":"clean"}],"do":[{"a":"status","who":"enemy","kind":"silence","turns":2}]}]'::jsonb, effect = 'After action, if you play Strike and this card hits clean: Opponent Silenced (card effects off) for 2 turns' where id = 'MG-013';
update cards set cost = 0, effect_json = '[{"hook":"onDraw","do":[{"a":"draw","who":"self","n":2}]}]'::jsonb, effect = 'Comes into play: Draw 2' where id = 'MG-018';
update cards set cost = 2, effect_json = '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"steal"},{"a":"status","who":"enemy","kind":"blockPlus","n":-1,"turns":1}]}]'::jsonb, effect = 'After action, if you play Strike: Steal the opponent''s card in this slot onto your Field, opponent''s Block stops −1 hit next turn' where id = 'MG-019';
update cards set cost = 1, effect_json = '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"enemyAction","a":"charge"}],"do":[{"a":"mulDmg","target":"this","pct":200}]}]'::jsonb, effect = 'Before action, if you play Strike and opponent plays Charge: This card dmg x2' where id = 'MG-020';
